select c.adjuster_id, a.full_name, a.region, a.hire_date, a.leave_date, c.cause, count(*) n, min(loss_date) first_loss, max(loss_date) last_loss, round(avg(pp),0) avg_paid, round(avg(case when c.cause='storm' then pp end),0) storm_avg, count(distinct substr(c.postcode,1,4)) pcs, sum((exists(select 1 from weather_events w where w.state=c.state and c.loss_date between w.start_date and w.end_date))::int) in_event, any_value(c.notes) note
from claims c join adjusters a using(adjuster_id) left join (select claim_id, sum(amount) pp from claim_payments where load_batch not like 'reload%' group by 1) p using(claim_id)
where c.repair_shop_id='RS-010' group by all order by n desc limit 12

